using Newtonsoft.Json;

namespace ticktick_WPF.Views.AI;

internal static class AIWebScrollPosition
{
	private const string ProbeLayoutFunction = "\r\n((expected) => {\r\n    if (innerWidth <= 0 || innerHeight <= 0 ||\r\n        Math.abs(innerWidth * devicePixelRatio - expected[0]) > 2 * devicePixelRatio ||\r\n        Math.abs(innerHeight * devicePixelRatio - expected[1]) > 2 * devicePixelRatio) return null;\r\n    const scroll = window.__ticktickHostScroll;\r\n    if (scroll && scroll.restoring && !scroll.cancelled && !scroll.ready) return null;\r\n    return JSON.stringify([location.href, innerWidth, innerHeight,\r\n        ...[document.scrollingElement, ...document.querySelectorAll('*')]\r\n            .filter(el => el && el.clientHeight > 0 &&\r\n                (el === document.scrollingElement || /(auto|scroll)/.test(getComputedStyle(el).overflowY)))\r\n            .map(el => [el.clientWidth, el.clientHeight, el.scrollHeight])]);\r\n})";

	internal const string Capture = "\r\n(() => {\r\n    const key = '__ticktickHostScroll';\r\n    window[key]?.cancel();\r\n    const items = [];\r\n    const root = document.scrollingElement;\r\n    for (const el of new Set([root, ...document.querySelectorAll('*')])) {\r\n        if (!el || el.clientHeight <= 0) continue;\r\n        if (el !== root && !/(auto|scroll)/.test(getComputedStyle(el).overflowY)) continue;\r\n        const rect = el.getBoundingClientRect();\r\n        if (rect.bottom <= 0 || rect.top >= innerHeight) continue;\r\n        const viewportTop = el === root ? 0 : Math.max(0, rect.top);\r\n        let anchor = null;\r\n        const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);\r\n        while (walker.nextNode()) {\r\n            const node = walker.currentNode;\r\n            if (!node.textContent.trim() || /^(SCRIPT|STYLE)$/.test(node.parentElement?.tagName)) continue;\r\n            const range = document.createRange();\r\n            range.selectNodeContents(node);\r\n            const boxes = range.getClientRects();\r\n            if (!boxes.length) continue;\r\n            const box = boxes[0];\r\n            if (box.top >= viewportTop && box.top < Math.min(rect.bottom, innerHeight)) {\r\n                anchor = { node, offset: box.top - viewportTop };\r\n                break;\r\n            }\r\n        }\r\n        items.push({ el, top: el.scrollTop, left: el.scrollLeft,\r\n            bottom: el.scrollHeight - el.clientHeight - el.scrollTop <= 4, anchor });\r\n    }\r\n    const events = ['wheel', 'pointerdown', 'touchstart', 'keydown'];\r\n    const state = { items, url: location.href, cancelled: false, timer: 0, frame: 0, cancel() {\r\n        state.cancelled = true;\r\n        clearTimeout(state.timer);\r\n        cancelAnimationFrame(state.frame);\r\n        for (const name of events) document.removeEventListener(name, state.cancel, true);\r\n        if (window[key] === state) delete window[key];\r\n    }};\r\n    for (const name of events) document.addEventListener(name, state.cancel, true);\r\n    state.timer = setTimeout(state.cancel, 2000);\r\n    window[key] = state;\r\n    return true;\r\n})();";

	private const string RestoreFunction = "\r\n((expected) => {\r\n    const state = window.__ticktickHostScroll;\r\n    if (!state || state.cancelled) return false;\r\n    state.restoring = true;\r\n    clearTimeout(state.timer);\r\n    state.timer = setTimeout(state.cancel, 2000);\r\n    let previousLayout = '';\r\n    let stableFrames = 0;\r\n    const restore = () => {\r\n        if (state.cancelled || window.__ticktickHostScroll !== state) return;\r\n        if (location.href !== state.url) { state.cancel(); return; }\r\n        state.frame = requestAnimationFrame(restore);\r\n        if (Math.abs(innerWidth * devicePixelRatio - expected[0]) > 2 * devicePixelRatio ||\r\n            Math.abs(innerHeight * devicePixelRatio - expected[1]) > 2 * devicePixelRatio) {\r\n            stableFrames = 0;\r\n            state.ready = false;\r\n            previousLayout = '';\r\n            return;\r\n        }\r\n        const layout = JSON.stringify([innerWidth, innerHeight, ...state.items.map(item =>\r\n            [item.el.clientWidth, item.el.clientHeight, item.el.scrollHeight])]);\r\n        if (layout !== previousLayout) { previousLayout = layout; stableFrames = 0; state.ready = false; }\r\n        // 连续布局帧一致后恢复；短期内继续观察滞后的重排，但不持续抢占网页滚动。\r\n        if (++stableFrames < 2 || stableFrames > 4) return;\r\n        for (const item of state.items) {\r\n            const el = item.el;\r\n            if (!el.isConnected || el.clientHeight <= 0) continue;\r\n            let top = item.top;\r\n            if (item.bottom) top = el.scrollHeight - el.clientHeight;\r\n            else if (item.anchor?.node.isConnected && el.contains(item.anchor.node)) {\r\n                const range = document.createRange();\r\n                range.selectNodeContents(item.anchor.node);\r\n                const box = range.getClientRects()[0];\r\n                const viewportTop = el === document.scrollingElement ? 0 : Math.max(0, el.getBoundingClientRect().top);\r\n                if (box) top = el.scrollTop + box.top - viewportTop - item.anchor.offset;\r\n            }\r\n            el.scrollTo({ top, left: item.left, behavior: 'instant' });\r\n        }\r\n        state.ready = stableFrames >= 4;\r\n    };\r\n    state.frame = requestAnimationFrame(restore);\r\n    return true;\r\n})";

	internal static string ProbeLayout(double pixelWidth, double pixelHeight)
	{
		return "\r\n((expected) => {\r\n    if (innerWidth <= 0 || innerHeight <= 0 ||\r\n        Math.abs(innerWidth * devicePixelRatio - expected[0]) > 2 * devicePixelRatio ||\r\n        Math.abs(innerHeight * devicePixelRatio - expected[1]) > 2 * devicePixelRatio) return null;\r\n    const scroll = window.__ticktickHostScroll;\r\n    if (scroll && scroll.restoring && !scroll.cancelled && !scroll.ready) return null;\r\n    return JSON.stringify([location.href, innerWidth, innerHeight,\r\n        ...[document.scrollingElement, ...document.querySelectorAll('*')]\r\n            .filter(el => el && el.clientHeight > 0 &&\r\n                (el === document.scrollingElement || /(auto|scroll)/.test(getComputedStyle(el).overflowY)))\r\n            .map(el => [el.clientWidth, el.clientHeight, el.scrollHeight])]);\r\n})(" + JsonConvert.SerializeObject(new double[2] { pixelWidth, pixelHeight }) + ");";
	}

	internal static string Restore(double pixelWidth, double pixelHeight)
	{
		return "\r\n((expected) => {\r\n    const state = window.__ticktickHostScroll;\r\n    if (!state || state.cancelled) return false;\r\n    state.restoring = true;\r\n    clearTimeout(state.timer);\r\n    state.timer = setTimeout(state.cancel, 2000);\r\n    let previousLayout = '';\r\n    let stableFrames = 0;\r\n    const restore = () => {\r\n        if (state.cancelled || window.__ticktickHostScroll !== state) return;\r\n        if (location.href !== state.url) { state.cancel(); return; }\r\n        state.frame = requestAnimationFrame(restore);\r\n        if (Math.abs(innerWidth * devicePixelRatio - expected[0]) > 2 * devicePixelRatio ||\r\n            Math.abs(innerHeight * devicePixelRatio - expected[1]) > 2 * devicePixelRatio) {\r\n            stableFrames = 0;\r\n            state.ready = false;\r\n            previousLayout = '';\r\n            return;\r\n        }\r\n        const layout = JSON.stringify([innerWidth, innerHeight, ...state.items.map(item =>\r\n            [item.el.clientWidth, item.el.clientHeight, item.el.scrollHeight])]);\r\n        if (layout !== previousLayout) { previousLayout = layout; stableFrames = 0; state.ready = false; }\r\n        // 连续布局帧一致后恢复；短期内继续观察滞后的重排，但不持续抢占网页滚动。\r\n        if (++stableFrames < 2 || stableFrames > 4) return;\r\n        for (const item of state.items) {\r\n            const el = item.el;\r\n            if (!el.isConnected || el.clientHeight <= 0) continue;\r\n            let top = item.top;\r\n            if (item.bottom) top = el.scrollHeight - el.clientHeight;\r\n            else if (item.anchor?.node.isConnected && el.contains(item.anchor.node)) {\r\n                const range = document.createRange();\r\n                range.selectNodeContents(item.anchor.node);\r\n                const box = range.getClientRects()[0];\r\n                const viewportTop = el === document.scrollingElement ? 0 : Math.max(0, el.getBoundingClientRect().top);\r\n                if (box) top = el.scrollTop + box.top - viewportTop - item.anchor.offset;\r\n            }\r\n            el.scrollTo({ top, left: item.left, behavior: 'instant' });\r\n        }\r\n        state.ready = stableFrames >= 4;\r\n    };\r\n    state.frame = requestAnimationFrame(restore);\r\n    return true;\r\n})(" + JsonConvert.SerializeObject(new double[2] { pixelWidth, pixelHeight }) + ");";
	}
}
